"""Direct coordinate counting. Trained diagnostic groups never enter development totals."""
from pathlib import Path
import json,hashlib
from collections import Counter
ROOT=Path(__file__).resolve().parent;V2=ROOT.parent/'coverage-v2'
read=lambda p:json.loads(p.read_text(encoding='utf-8-sig'))
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
manifest=read(ROOT/'paired-manifest.json');rows={r['id']:r for r in manifest['rows']}
corpus=read(ROOT/'development-corpus.json');frames={f['id']:f for f in corpus['frames']}
train=read(ROOT/'training-pair-corpus.json') if (ROOT/'training-pair-corpus.json').exists() else None
training={f['id']:f for f in train['frames']} if train else {}
all_frames={**frames,**training};summaries=[];wrong=[];evidence=[]
paired_dev={f['id'] for f in corpus['frames'] if f['id'].endswith(tuple(f'{n:06d}' for n in range(776,788)))}
def count(model,mode,predictions):
    selected=[p for p in predictions if p['id'].split('@')[0] in all_frames]
    assert len({p['id'] for p in selected})==len(selected)
    buckets={}
    for p in selected:
        fid=p['id'].split('@')[0];f=all_frames[fid];s=p['selected'];trained=fid in training
        groups=(['trained-pairs-fit-only'] if trained else ['all-development'])
        if not trained and f['state']=='present':groups+=[rows[fid]['sceneGroup']]
        if fid in paired_dev:groups+=['heldout-stationary-776-787']
        for group in groups:
            c=buckets.setdefault(group,Counter());c['frames']+=1
            if f['state']=='present':
                c['present']+=1
                if s is None:c['miss']+=1
                elif all(s[k]==f['expected'][k] for k in 'xyz'):c['correct']+=1
                else:c['wrong']+=1;c['signErrors']+=any(s[k] and f['expected'][k] and (s[k]<0)!=(f['expected'][k]<0) for k in 'xyz')
            elif f['state']=='absent':c['absent']+=1;c['falsePositive']+=s is not None
            else:c['unknown']+=1
        if f['state']=='present' and s is not None and not all(s[k]==f['expected'][k] for k in 'xyz') or f['state']=='absent' and s is not None:
            wrong.append({'model':model,'mode':mode,'id':fid,'trainedFitOnly':trained,'expected':f['expected'],'selected':s,'rawText':p.get('rawText')})
    for group,c in buckets.items():
        summary={k:c[k] for k in ['frames','present','correct','wrong','miss','signErrors','absent','falsePositive','unknown']}
        assert summary['correct']+summary['wrong']+summary['miss']==summary['present']
        if group=='all-development':assert summary['frames']==319 and summary['present']==170
        summaries.append({'model':model,'mode':mode,'group':group,**summary})

for model,path in [('initial',V2/'replay-initial.json'),('v2-positive',V2/'replay-coverage-positive.json'),
                   ('pair-raw',ROOT/'replay-pair-raw.json'),('pair-routes',ROOT/'replay-pair-routes.json')]:
    if not path.exists():continue
    raw=read(path);evidence.append({'model':model,'path':str(path),'sha256':sha(path)})
    for mode,items in raw['pipelines'].items():
        count(model,mode,items)
yolo_folder=Path(r'C:\Dcode\WWMAP-TOOLS\out\coordinate-minimap-check\ocr-full-session')
yolo=read(yolo_folder/'yolo.json');predictions=[p for p in yolo['results'] if p['id'].endswith('@upstream-band')]
count('yolo','yolo',predictions);evidence.append({'model':'yolo','path':str(yolo_folder/'yolo.json'),'sha256':sha(yolo_folder/'yolo.json')})
report={'scope':'170 fixed same-session development XYZ,141 absent,8 unknown. 27 paired trained-fit frames are separate. No independent session acceptance.',
    'productionChanged':False,'sourceManifestSHA256':sha(ROOT/'paired-manifest.json'),'summary':summaries,'wrongCases':wrong,'sourceEvidence':evidence}
(ROOT/'paired-report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
for s in summaries:
    if s['mode'] in ['ppocr-contrast-clock','ppocr-corroborated-clock','yolo'] and s['group'] in ['all-development','heldout-stationary-776-787','snow-pale-mixed','trained-pairs-fit-only']:
        print(s['model'],s['mode'],s['group'],s['correct'],s['wrong'],s['miss'],'FP',s['falsePositive'],flush=True)
